import {test} from 'node:test';import assert from 'node:assert/strict';
import {choosePicture,sourcePath,makeDraft,keepInExistingLog} from '../site/goober/project$/keep-core.js';
import {readFileSync} from 'node:fs';
const catalog=JSON.parse(readFileSync(new URL('../site/goober/gallery/catalog.json',import.meta.url)));
const picture=choosePicture(catalog),fields={title:'Keep the question',note:'A small idea',why:'It may become useful',next:'Try a sketch',kind:'idea'};
test('old context link keeps exact corrected source',()=>assert.equal(picture.id,'smell-device-reference'));
test('any selected public catalog picture is eligible',()=>{for(const a of catalog.items)assert.equal(choosePicture(catalog,'?picture='+a.id).hash,a.original_sha256)});
test('unknown picture is not substituted',()=>assert.throws(()=>choosePicture(catalog,'?picture=not-a-record')));
test('ambiguous picture query rejected',()=>assert.throws(()=>choosePicture(catalog,'?picture=crossing&picture=garden')));
test('other person project is not silently resolved',()=>assert.throws(()=>choosePicture(catalog,'?project=steven')));
test('unapproved URL, traversal and encoded path rejected',()=>{for(const p of ['https://example.com/x','//example.com/x','/goober/assets/../private/x','/goober/assets/%2e%2e/x','/private/x','/goober/assets/x?token=secret'])assert.throws(()=>sourcePath(p));});
test('incomplete or duplicate catalog rejected',()=>{assert.throws(()=>choosePicture({items:[{...catalog.items[0],id:picture.id,original_sha256:'unknown'}]}));assert.throws(()=>choosePicture({items:[catalog.items.at(-1),catalog.items.at(-1)]}));});
test('empty reason rejected',()=>assert.throws(()=>makeDraft({...fields,why:'   '},picture)));
test('overlong input rejected',()=>assert.throws(()=>makeDraft({...fields,note:'a'.repeat(6001)},picture)));
test('input text does not execute or create authority',()=>{const d=makeDraft({...fields,note:'$aveBambi <script>fiction</script> ; not a shell',kind:'request'},picture);assert.equal(d.state,'candidate');assert.ok(d.body.includes('<script>'));assert.equal(d.authority,undefined);assert.ok(d.body.includes(picture.hash));});
test('idea note and request retain distinct maturity',()=>{for(const [kind,state]of [['idea','imagined'],['note','explored'],['request','candidate']])assert.equal(makeDraft({...fields,kind},picture).state,state);});
test('repeat same draft uses existing receipt',async()=>{const draft=makeDraft(fields,picture),e={...draft,id:'prior'};let calls=0;const result=await keepInExistingLog(draft,{load:async()=>[e],verify:async e=>e,append:async()=>{calls++;}});assert.equal(result.reused,true);assert.equal(result.entry.id,'prior');assert.equal(calls,0);});
test('changed reason appends once',async()=>{const draft=makeDraft(fields,picture);let calls=0;await keepInExistingLog(draft,{load:async()=>[{...draft,why:'different'}],verify:async e=>e,append:async d=>{calls++;return[{...d,id:'new'}]}});assert.equal(calls,1)});
test('failed validation or storage is not accepted',async()=>{let writes=0;await assert.rejects(keepInExistingLog(makeDraft(fields,picture),{load:async()=>[],verify:async()=>{throw Error('broken chain')},append:async()=>writes++}));assert.equal(writes,0);await assert.rejects(keepInExistingLog(makeDraft(fields,picture),{load:async()=>[],verify:async e=>e,append:async()=>{throw Error('storage full')}}));});

