const {chromium}=require('/usr/local/lib/node_modules/playwright');const fs=require('node:fs');
(async()=>{const browser=await chromium.launch({args:['--no-sandbox']});const c=await browser.newContext({viewport:{width:1440,height:960},serviceWorkers:'block'});const p=await c.newPage(),checks=[],errors=[],requests=[];const root=process.env.ORIGIN||'http://127.0.0.1:4951';p.on('pageerror',e=>errors.push(e.message));p.on('request',r=>requests.push(r.url()));const ok=(name,passed)=>{checks.push({name,passed:!!passed});if(!passed)throw Error(name)};
async function storeCount(page){return page.evaluate(async()=>{const m=await import('/goober/project$/saedow-store.js');return (await m.load()).length;});}
try{
 await p.goto(root+'/goober/#log',{waitUntil:'networkidle'});await p.waitForSelector('.local-chip:has-text("DEVICE-LOCAL")');await p.getByLabel('Title',{exact:true}).fill('Before this feature · preserve me');await p.getByRole('button',{name:'Keep it here',exact:false}).click();await p.waitForSelector('.entry h3:has-text("Before this feature")');
 await p.goto(root+'/goober/project$/#cockpit',{waitUntil:'networkidle'});await p.waitForSelector('body[data-keep-ready=true]');ok('same project opens the exact corrected picture',await p.locator('#picture-title').innerText().then(t=>t.includes('corrected screenshot')));ok('opening does not save another entry',await storeCount(p)===1);ok('existing database and entry remain',await p.evaluate(async()=>{const m=await import('./saedow-store.js');return (await m.verify(await m.load()))[0].title.startsWith('Before this feature');}));
 await p.screenshot({path:'/tmp/savebambi-page-desktop.png',fullPage:true});
 await p.getByRole('button',{name:'Keep with this project',exact:true}).click();ok('reason required, no silent partial save',await storeCount(p)===1);
 await p.getByLabel('Give the thread a name').fill('Do not lose the useful part');await p.getByLabel('What do you want to remember?').fill('A fictional reference can spark a good little scene. <tag> is plain text.');await p.getByLabel('Why does it matter?').fill('A playful way to connect the world and the project.');await p.getByLabel('One small next step',{exact:false}).fill('Sketch one observation tool.');
 await p.evaluate(()=>{const f=document.querySelector('form');f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));});await p.waitForSelector('#result:not([hidden])');ok('double submit appends only one note',await storeCount(p)===2);ok('save shows committed receipt',await p.locator('#saved-hash').textContent().then(x=>/^[a-f0-9]{64}$/.test(x??'')));ok('no injected markup in result',await p.locator('tag').count()===0);
 const saved=await p.evaluate(async()=>{const m=await import('./saedow-store.js');return (await m.verify(await m.load())).at(-1);});ok('source, meaning and next step saved together',saved.why.startsWith('A playful')&&saved.next_proof==='Sketch one observation tool.'&&saved.body.includes('#smell-device-reference')&&saved.source.startsWith('saelion://art/sha256/'));ok('entry is imagined, local, and has no action authority',saved.state==='imagined'&&saved.scope==='device-local'&&saved.authority==='none'&&saved.acceptance==='self-reported');
 await p.evaluate(()=>document.querySelector('form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true})));await p.waitForSelector('#status:has-text("already in your field log")');ok('exact retry reuses the existing note',await storeCount(p)===2);
 await p.getByRole('link',{name:'See it in your field log',exact:false}).click();await p.waitForSelector('.entry h3:has-text("Do not lose the useful part")');ok('native field log reads the new entry without import',await p.locator('.entry').count()===2);await p.reload({waitUntil:'networkidle'});await p.waitForSelector('.entry h3:has-text("Do not lose the useful part")');ok('saved entry survives main-app reload',true);
 const [download]=await Promise.all([p.waitForEvent('download'),p.getByRole('button',{name:'Export',exact:false}).click()]);await download.saveAs('/tmp/savebambi-original-export.json');const packet=JSON.parse(fs.readFileSync('/tmp/savebambi-original-export.json','utf8'));ok('normal app export retains the same schema and all notes',packet.schema==='saedow/0.1'&&packet.entries.length===2&&packet.entries[1].hash===saved.hash);
 await p.goto(root+'/goober/gallery/#garden',{waitUntil:'networkidle'});await p.waitForSelector('dialog[open]');await p.getByRole('link',{name:'Keep this with your project',exact:false}).click();await p.waitForSelector('body[data-keep-ready=true]');ok('gallery hands off another exact picture',p.url().includes('picture=garden')&&(await p.locator('#picture-title').innerText())==='EverDelve: Garden Central');ok('gallery selection does not save on its own',await storeCount(p)===2);
 for(const width of [320,390,768,1440]){await p.setViewportSize({width,height:844});ok('project page no overflow '+width,await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));if(width===390)await p.screenshot({path:'/tmp/savebambi-page-mobile.png',fullPage:true});}
 await p.goto(root+'/goober/project$/?picture=missing#cockpit',{waitUntil:'networkidle'});await p.waitForSelector('body[data-keep-ready=error]');ok('unknown image is not substituted or saved',await p.locator('#picture-block').isHidden()&&await p.locator('#keep-submit').isDisabled()&&await storeCount(p)===2);
 await p.goto(root+'/goober/project$/?project=steven',{waitUntil:'networkidle'});await p.waitForSelector('body[data-keep-ready=error]');ok('another project cannot be opened through this hook',await p.locator('#status').innerText().then(x=>x.includes('scoped to Goober')));
 await p.goto(root+'/goober/project$/?picture=crossing',{waitUntil:'networkidle'});await p.waitForSelector('body[data-keep-ready=true]');
 const concurrency=await p.evaluate(async()=>{const m=await import('./saedow-store.js');const before=(await m.load()).length,d={kind:'note',state:'explored',title:'Concurrent fixture A',body:'',why:'test only',next_proof:'',source:'test-fixture'};const results=await Promise.allSettled([m.append(d),m.append({...d,title:'Concurrent fixture B'})]);const notes=await m.verify(await m.load());return {before,after:notes.length,success:results.filter(x=>x.status==='fulfilled').length,first:notes[0].title};});ok('concurrent append never loses existing notes',concurrency.after===concurrency.before+concurrency.success&&concurrency.first.startsWith('Before this feature'));
 ok('all runtime requests remain on this site',requests.every(u=>new URL(u).origin===root));ok('no JavaScript runtime exceptions',errors.length===0);
}catch(e){checks.push({name:'browser run failure',passed:false,error:String(e)});}
const isolated=await browser.newContext({serviceWorkers:'block'}),q=await isolated.newPage();try{await q.goto(root+'/goober/project$/',{waitUntil:'networkidle'});await q.waitForSelector('body[data-keep-ready=true]');await q.evaluate(async()=>{const m=await import('./saedow-store.js');await m.append({kind:'note',state:'explored',title:'Tamper fixture',body:'',why:'test only',next_proof:'',source:'test-fixture'});await new Promise((resolve,reject)=>{const r=indexedDB.open('anewgam-goober-v1',1);r.onsuccess=()=>{const db=r.result,tx=db.transaction('log','readwrite'),store=tx.objectStore('log'),g=store.get('entries');g.onsuccess=()=>{g.result[0].body='changed outside the chain';store.put(g.result,'entries');};tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>reject(tx.error);};});});await q.reload({waitUntil:'networkidle'});await q.waitForSelector('body[data-keep-ready=error]');ok('tampered history blocks writes, not silently repaired',await q.locator('#keep-submit').isDisabled()&&await storeCount(q)===1);}catch(e){checks.push({name:'tamper fixture test failed',passed:false,error:String(e)});}await isolated.close();
const nojs=await browser.newContext({javaScriptEnabled:false}),r=await nojs.newPage();await r.goto(root+'/goober/project$/');ok('without JavaScript only explicit links remain, save disabled',await r.locator('#keep-submit').isDisabled()&&await r.locator('a[href="../#log"]').count()>0);await nojs.close();
const report={tested_at:new Date().toISOString(),origin:root,environment:'Fresh isolated Chromium profiles; synthetic notes, no user account data; service workers blocked to test this feature',checks,errors};fs.writeFileSync('/tmp/savebambi-browser.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));await browser.close();})().catch(e=>{console.error(e);process.exit(1)});

